#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "2mm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("D");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, D[i][j]);
    }
  POLYBENCH_DUMP_END("D");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version:
   - Uses restrict-qualified VLA pointers for better alias analysis.
   - Separates initialization and scaling from the main products.
   - Applies cache blocking (tiling) for all three matrix dimensions.
   - Orders inner loops so that the innermost index is always the
     contiguous dimension in memory, improving spatial locality.
   - Provides vectorization-friendly inner loops (j as innermost).
*/
static
#ifdef __GNUC__
__attribute__((noinline))
#endif
void kernel_2mm(int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  /* Reintroduce the true pointer types with explicit dimensions and
     restrict qualifiers to help the optimizer.  The original
     parameters decay to the same pointer types, so this is
     semantically equivalent but gives the compiler stronger guarantees
     about aliasing. */
  DATA_TYPE (*restrict tmp_)[nj] = (DATA_TYPE (*restrict)[nj]) tmp;
  DATA_TYPE (*restrict A_)[nk]   = (DATA_TYPE (*restrict)[nk]) A;
  DATA_TYPE (*restrict B_)[nj]   = (DATA_TYPE (*restrict)[nj]) B;
  DATA_TYPE (*restrict C_)[nl]   = (DATA_TYPE (*restrict)[nl]) C;
  DATA_TYPE (*restrict D_)[nl]   = (DATA_TYPE (*restrict)[nl]) D;

  /* Use PolyBench loop bounds (typically compile-time constants)
     for the iteration spaces, as in the original kernel. */
  const int ni0 = _PB_NI;
  const int nj0 = _PB_NJ;
  const int nk0 = _PB_NK;
  const int nl0 = _PB_NL;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

  /* Blocking factors chosen to balance cache reuse on typical
     x86-64 systems. They do not need to divide the problem sizes;
     edge tiles are handled explicitly. */
  const int BI = 32;
  const int BJ = 32;
  const int BK = 32;

#pragma scop
  /* D := alpha*A*B*C + beta*D  (blocked implementation) */

  /* 1. Initialize tmp to zero (tmp[i][j] = 0). */
  for (int i = 0; i < ni0; ++i)
  {
    DATA_TYPE *restrict tmp_row = &tmp_[i][0];
#ifdef __GNUC__
#pragma GCC ivdep
#endif
    for (int j = 0; j < nj0; ++j)
      tmp_row[j] = SCALAR_VAL(0.0);
  }

  /* 2. Scale D by beta (D[i][j] *= beta). */
  for (int i = 0; i < ni0; ++i)
  {
    DATA_TYPE *restrict d_row = &D_[i][0];
#ifdef __GNUC__
#pragma GCC ivdep
#endif
    for (int j = 0; j < nl0; ++j)
      d_row[j] *= beta_local;
  }

  /* 3. tmp = alpha * A * B
     Original form:
        for i
          for j
            tmp[i][j] = 0;
            for k
              tmp[i][j] += alpha * A[i][k] * B[k][j];

     New form:
       - Separate initialization already done above.
       - Use i/k/j blocking with j innermost for contiguous access to
         B[k][j] and tmp[i][j].
       - For each (k, i) pair in the block, reuse A[i][k] across the
         entire j-tile.
  */
  for (int ii = 0; ii < ni0; ii += BI)
  {
    const int i_max = (ii + BI < ni0) ? (ii + BI) : ni0;

    for (int kk = 0; kk < nk0; kk += BK)
    {
      const int k_max = (kk + BK < nk0) ? (kk + BK) : nk0;

      for (int jj = 0; jj < nj0; jj += BJ)
      {
        const int j_max = (jj + BJ < nj0) ? (jj + BJ) : nj0;
        const int j_len = j_max - jj;

        for (int k = kk; k < k_max; ++k)
        {
          const DATA_TYPE *restrict b_row = &B_[k][jj]; /* B[k][jj..j_max) */

          for (int i = ii; i < i_max; ++i)
          {
            DATA_TYPE *restrict tmp_row = &tmp_[i][jj]; /* tmp[i][jj..j_max) */
            const DATA_TYPE a_ik = alpha_local * A_[i][k];

            int j = 0;
#ifdef __GNUC__
#pragma GCC ivdep
#endif
            for (; j + 3 < j_len; j += 4)
            {
              tmp_row[j+0] += a_ik * b_row[j+0];
              tmp_row[j+1] += a_ik * b_row[j+1];
              tmp_row[j+2] += a_ik * b_row[j+2];
              tmp_row[j+3] += a_ik * b_row[j+3];
            }
            for (; j < j_len; ++j)
            {
              tmp_row[j] += a_ik * b_row[j];
            }
          }
        }
      }
    }
  }

  /* 4. D += tmp * C
     Original form:
        for i
          for j
            D[i][j] *= beta;
            for k
              D[i][j] += tmp[i][k] * C[k][j];

     New form:
       - Scaling by beta already done above.
       - Use the same blocked i/k/j structure with j innermost for
         contiguous access to C[k][j] and D[i][j].
       - For each (k, i) pair in the block, reuse tmp[i][k] across
         the entire j-tile.
  */
  for (int ii = 0; ii < ni0; ii += BI)
  {
    const int i_max = (ii + BI < ni0) ? (ii + BI) : ni0;

    for (int kk = 0; kk < nj0; kk += BK)
    {
      const int k_max = (kk + BK < nj0) ? (kk + BK) : nj0;

      for (int jj = 0; jj < nl0; jj += BJ)
      {
        const int j_max = (jj + BJ < nl0) ? (jj + BJ) : nl0;
        const int j_len = j_max - jj;

        for (int k = kk; k < k_max; ++k)
        {
          const DATA_TYPE *restrict c_row = &C_[k][jj]; /* C[k][jj..j_max) */

          for (int i = ii; i < i_max; ++i)
          {
            DATA_TYPE *restrict d_row = &D_[i][jj]; /* D[i][jj..j_max) */
            const DATA_TYPE tmp_ik = tmp_[i][k];

            int j = 0;
#ifdef __GNUC__
#pragma GCC ivdep
#endif
            for (; j + 3 < j_len; j += 4)
            {
              d_row[j+0] += tmp_ik * c_row[j+0];
              d_row[j+1] += tmp_ik * c_row[j+1];
              d_row[j+2] += tmp_ik * c_row[j+2];
              d_row[j+3] += tmp_ik * c_row[j+3];
            }
            for (; j < j_len; ++j)
            {
              d_row[j] += tmp_ik * c_row[j];
            }
          }
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(tmp,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NJ,NL,nj,nl);
  POLYBENCH_2D_ARRAY_DECL(D,DATA_TYPE,NI,NL,ni,nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_2mm (ni, nj, nk, nl,
	      alpha, beta,
	      POLYBENCH_ARRAY(tmp),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(D)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);

  return 0;
}
