/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_2mm [[gnu::flatten, gnu::noinline]] (int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop
  /* D := alpha*A*B*C + beta*D
   *
   * Optimized implementation:
   *  - Use i-k-j traversal for both matrix multiplications to make
   *    accesses to B, C, tmp and D contiguous in memory.
   *  - Flatten the 2D arrays into 1D restrict-qualified pointers to
   *    help the compiler with alias analysis and vectorization.
   *  - Keep the accumulation order over k for each element identical
   *    to the original code.
   */

  /* Flattened, restrict-qualified views of the matrices. */
  DATA_TYPE * restrict tmp_ = &tmp[0][0];
  DATA_TYPE * restrict A_   = &A[0][0];
  DATA_TYPE * restrict B_   = &B[0][0];
  DATA_TYPE * restrict C_   = &C[0][0];
  DATA_TYPE * restrict D_   = &D[0][0];

  /* Iteration bounds (possibly different from raw sizes if PolyBench
     uses cropped loop bounds). */
  const int ni_it = _PB_NI;
  const int nj_it = _PB_NJ;
  const int nk_it = _PB_NK;
  const int nl_it = _PB_NL;

  /* Physical row strides (second dimension sizes of the VLAs). */
  const int nj_dim = nj;
  const int nk_dim = nk;
  const int nl_dim = nl;

  /* --------------------------------------------------------------------
   * Stage 1: tmp = alpha * A * B
   * ------------------------------------------------------------------*/

  /* Initialize the part of tmp that will be used.  This replaces the
     per-element initialization in the original i-j-k nest and enables
     an i-k-j traversal while preserving the per-element accumulation
     order over k. */
  for (i = 0; i < ni_it; ++i) {
    DATA_TYPE * restrict tmp_row = tmp_ + (size_t)i * nj_dim;
    for (j = 0; j < nj_it; ++j)
      tmp_row[j] = SCALAR_VAL(0.0);
  }

  /* Matrix multiplication in i-k-j order:
     For each (i,k):
       - A[i][k] is read once,
       - we stream over contiguous rows B[k][*] and tmp[i][*].
     This improves cache locality and makes the innermost loop a simple
     AXPY, which is easy to vectorize. */
  for (i = 0; i < ni_it; ++i) {
    const DATA_TYPE * restrict A_row   = A_   + (size_t)i * nk_dim;
    DATA_TYPE       * restrict tmp_row = tmp_ + (size_t)i * nj_dim;

    for (k = 0; k < nk_it; ++k) {
      const DATA_TYPE a_ik_alpha = alpha * A_row[k];
      const DATA_TYPE * restrict B_row = B_ + (size_t)k * nj_dim;

      for (j = 0; j < nj_it; ++j) {
        tmp_row[j] += a_ik_alpha * B_row[j];
      }
    }
  }

  /* --------------------------------------------------------------------
   * Stage 2: D = beta * D + tmp * C
   * ------------------------------------------------------------------*/

  /* First scale D by beta, for the portion that will be updated.  This
     keeps the main multiply-add loop free of extra work. */
  for (i = 0; i < ni_it; ++i) {
    DATA_TYPE * restrict D_row = D_ + (size_t)i * nl_dim;
    for (j = 0; j < nl_it; ++j)
      D_row[j] *= beta;
  }

  /* D += tmp * C in i-k-j order:
       D[i][j] += tmp[i][k] * C[k][j]
     Here:
       - tmp is read by rows,
       - C is read by rows,
       - D is updated by rows.
     The sequence of updates over k for each D(i,j) matches the
     original implementation. */
  for (i = 0; i < ni_it; ++i) {
    const DATA_TYPE * restrict tmp_row = tmp_ + (size_t)i * nj_dim;
    DATA_TYPE       * restrict D_row   = D_   + (size_t)i * nl_dim;

    for (k = 0; k < nj_it; ++k) {
      const DATA_TYPE tmp_ik = tmp_row[k];
      const DATA_TYPE * restrict C_row = C_ + (size_t)k * nl_dim;

      for (j = 0; j < nl_it; ++j) {
        D_row[j] += tmp_ik * C_row[j];
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
