  /* D := alpha*A*B*C + beta*D */

  /* 1. Initialize tmp to 0.
        Looping over contiguous rows improves cache behavior and
        provides a simple pattern for vectorization. */
  for (i = 0; i < _PB_NI; ++i)
  {
    DATA_TYPE * restrict tmp_row = tmp_[i];
#pragma GCC ivdep
    for (j = 0; j < _PB_NJ; ++j)
      tmp_row[j] = SCALAR_VAL(0.0);
  }

  /* 2. tmp := alpha * A * B
        Original order: (i,j,k) with k innermost.
        New order: (i,k,j). For each (i,k) we stream over full
        rows of B and tmp, which are contiguous in memory.
        This improves data locality and allows efficient SIMD.

        Mathematically:
          tmp[i][j] = sum_k alpha * A[i][k] * B[k][j]
        is unchanged; only the iteration order differs. */
  for (i = 0; i < _PB_NI; ++i)
  {
    DATA_TYPE * restrict tmp_row = tmp_[i];
    for (k = 0; k < _PB_NK; ++k)
    {
