        Simple row-wise scaling, again using contiguous access. */
  for (i = 0; i < _PB_NI; ++i)
  {
    DATA_TYPE * restrict D_row = D_[i];
#pragma GCC ivdep
    for (j = 0; j < _PB_NL; ++j)
      D_row[j] *= beta;
  }

  /* 4. D := D + tmp * C
        Original order: (i,j,k) with k innermost.
        New order: (i,k,j). For each (i,k) we reuse tmp[i][k] and
        stream over full rows of C and D.

        Mathematically:
          D[i][j] = beta * D_orig[i][j]
                    + sum_k tmp[i][k] * C[k][j]
        is preserved; only the loop nesting and accumulation
        order change. */
  for (i = 0; i < _PB_NI; ++i)
  {
    DATA_TYPE * restrict D_row      = D_[i];
    const DATA_TYPE * restrict tmp_row = tmp_[i];
    for (k = 0; k < _PB_NJ; ++k)
    {
      const DATA_TYPE tmp_ik = tmp_row[k];
      const DATA_TYPE * restrict C_row = C_[k];
#pragma GCC ivdep
      for (j = 0; j < _PB_NL; ++j)
        D_row[j] += tmp_ik * C_row[j];
    }
  }
#pragma endscop

}


